previewCss:
.darma-loader-abacus-slide {
  position: relative;
  width: 52px;
  height: 38px;
}
.darma-loader-abacus-slide::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 7px;
  height: 2px;
  border-radius: 2px;
  background: #c7d2fe;
  box-shadow: 0 12px 0 #c7d2fe, 0 24px 0 #c7d2fe;
}
.darma-loader-abacus-slide i {
  position: absolute;
  left: 0;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--loader-color, #6366f1);
  animation: darma-loader-abacus-slide-slide 1.3s ease-in-out infinite;
}
.darma-loader-abacus-slide i:nth-child(1) { top: 2px; animation-delay: 0s; }
.darma-loader-abacus-slide i:nth-child(2) { top: 14px; animation-delay: 0.2s; animation-direction: reverse; }
.darma-loader-abacus-slide i:nth-child(3) { top: 26px; animation-delay: 0.4s; }
@keyframes darma-loader-abacus-slide-slide {
  0%, 100% { left: 0; }
  50% { left: calc(100% - 12px); }
}

